def verb_passage(n):
    text,answers=PASSAGES[(n-1)%10];name=['Riya','Meera'][(n-1)//10]
    return dict(prompt='Complete the passage with the correct forms of the bracketed verbs. Use the past narrative context and the grammatical cues. Do not copy the passage; number the eight answers.\n\n'+text.format(name=name),marks=4,answer='½ mark each. '+ '; '.join(f'{i+1}. {a}' for i,a in enumerate(answers.split('|'))))
